@app.cell
def _(mo):
    mo.md('## Optional: download ImageNet directly from Hugging Face\nAccept access conditions at [ILSVRC/imagenet-1k](https://huggingface.co/datasets/ILSVRC/imagenet-1k) first. This uses14 validation Parquet shards (several GB), retains the SAME frozen1,000 original filenames and never downloads training shards. Original names must be present; otherwise preparation stops without substituting rows. Token is passed in memory/environment, not written into settings or worker files. Authenticated access/schema could not be tested locally. Main experiment settings remain unchanged.')
    hf_form = mo.ui.dictionary({'token': mo.ui.text(value='', kind='password', label='HF read token; leave blank if HF_TOKEN is already configured'), 'destination': mo.ui.text(value='/marimo/data/imagenet_selected_originals', label='Selected original image destination'), 'cache': mo.ui.text(value='/marimo/hf_imagenet_cache', label='Validation shard cache; several GB required'), 'job_root': mo.ui.text(value='/marimo/imagenet_hf_prepare', label='Preparation progress folder'), 'accepted': mo.ui.checkbox(value=False, label='My HF account has access and I have accepted the dataset conditions')}).form(submit_button_label='Apply download settings')
    hf_form
    return (hf_form,)

@app.cell
def _(mo):
    hf_start = mo.ui.run_button(label='Download / verify fixed ImageNet subset')
    hf_refresh = mo.ui.run_button(label='Refresh download progress')
    mo.hstack([hf_start, hf_refresh])
    return (hf_start, hf_refresh)

@app.cell
def _(mo, Path, hf_form, hf_start, download_jobs, hf_transport, fixed_imagenet_ids):
    mo.stop(not hf_start.value)
    mo.stop(hf_form.value is None, mo.md('Apply download settings first.'))
    mo.stop(not hf_form.value['accepted'], mo.md('Accept the dataset access conditions and tick the acknowledgement.'))
    import os as _os
    _token = hf_form.value['token'] or _os.environ.get('HF_TOKEN')
    mo.stop(not _token, mo.md('Enter an HF read token or load HF_TOKEN first.'))
    _params = {k: str(Path(hf_form.value[k]).expanduser().resolve()) for k in ['destination', 'cache', 'job_root']}
    _params['ids'] = fixed_imagenet_ids
    download_jobs.launch(_params, _token, hf_transport)
    mo.md('Preparation submitted. Click Refresh download progress.')
    return

@app.cell
def _(mo, Path, json, hf_form, hf_refresh, download_jobs):
    _refresh = hf_refresh.value
    mo.stop(hf_form.value is None, mo.md('Apply download settings to inspect preparation.'))
    _state = download_jobs.status(str(Path(hf_form.value['job_root']).expanduser().resolve()))
    mo.vstack([mo.md('```json\n' + json.dumps({k: v for (k, v) in _state.items() if k != 'log_tail'}, indent=2) + '\n```'), mo.md('```text\n' + _state.get('log_tail', 'No preparation worker started yet.') + '\n```')])
    return

