@app.cell
def _(mo, Path, json, start_button, form, experiment_jobs, worker_source, fixed_imagenet_ids):
    mo.stop(not start_button.value)
    mo.stop(form.value is None, mo.md('Apply experiment settings first.'))
    _settings = experiment_jobs.validate(dict(form.value, task='input_audit'))
    if _settings['dataset'] not in ['all', 'ffhq', 'div2k', 'urban100', 'imagenet']:
        raise ValueError('NB03 covers DIV2K, Urban100 and ImageNet only.')
    if _settings['dataset'] in ['all', 'imagenet']:
        _source = Path(_settings['imagenet_source']).expanduser().resolve()
        _manifest = _source / 'hf_source_manifest.json'
        mo.stop(not _manifest.is_file(), mo.md('ImageNet preparation is not ready. Complete HF download and check imagenet_source.'))
        _prepared = json.loads(_manifest.read_text())
        if not _prepared.get('completed') or _prepared.get('selected_ids') != fixed_imagenet_ids:
            raise ValueError('Preparation must contain the exact fixed 1,000 ImageNet IDs.')
        if len(_prepared.get('images', [])) != 1000:
            raise ValueError('Prepared manifest must contain all1,000 original images.')
        import hashlib as _hashlib
        for _row in _prepared['images']:
            _p = _source / _row['file']
            if not _p.is_file() or _hashlib.sha256(_p.read_bytes()).hexdigest() != _row['sha256']:
                raise ValueError('Prepared source is missing or damaged: ' + _row['file'])
    import hashlib as _hashlib
    if _hashlib.sha256(Path(_settings['inputs_file']).read_bytes()).hexdigest() != '72d03c845f6688c48031970266b7f18037ee19cbf3e72e630a75e57215a2c419':
        raise ValueError('Input Tables ZIP differs from the verified fixed release.')
    _info = experiment_jobs.launch(_settings, worker_source)
    _job = Path(_info['job_directory'])
    if _settings['dataset'] in ['all', 'imagenet']:
        (_job / 'experiment').mkdir(exist_ok=True)
        (_job / 'experiment' / 'imagenet_download_provenance.json').write_bytes(_manifest.read_bytes())
    mo.md('Worker submitted. Click Refresh experiment progress and files.')
    return

@app.cell
def _(mo, Path, json, form, refresh_button, experiment_jobs):
    _refresh = refresh_button.value
    mo.stop(form.value is None, mo.md('Apply experiment settings to inspect this run.'))
    _job = Path(form.value['output_root']).expanduser().resolve() / (form.value['run_label'] + '_FOCUS')
    _state = experiment_jobs.status(_job)
    _downloads = _job.parent.parent / 'paper2_focus_downloads'
    _parts = [mo.md('```json\n' + json.dumps({k: v for (k, v) in _state.items() if k != 'log_tail'}, indent=2) + '\n```'), mo.md('```text\n' + _state.get('log_tail', 'No worker output yet. Complete preparation, then Start.') + '\n```'), mo.md('Download the completed _FINAL.zip from **' + str(_downloads) + '**. Refresh is manual.')]
    if _downloads.exists():
        _parts.append(mo.md('\n'.join(('- ' + _p.name for _p in sorted(_downloads.iterdir()) if _p.is_file()))))
    mo.vstack(_parts)
    return
if __name__ == '__main__':
    app.run()
